use vstd::prelude::*;

verus! {
    // Compute the “default” coefficient:
    // if c is 1×1, return that single entry, otherwise return 0.0.
    fn default_value(c: &Vec<Vec<f32>>) -> (val: f32)
        requires
            // grid is non‐empty
            c.len() > 0,
            // each row is non‐empty
            forall|i: usize| i < c.len() ==> c[i].len() > 0,
        ensures
            // spec: exactly the 1×1 entry if there is one, else zero
            val == if c.len() == 1 && c[0].len() == 1 {
                       c[0][0]
                   } else {
                       0.0_f32
                   },
    {
        if c.len() == 1 && c[0].len() == 1 {
            c[0][0]
        } else {
            0.0_f32
        }
    }

    // Build an output vector of the same length as x (and y),
    // filled everywhere with default_value(c).
    fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> (out: Vec<f32>)
        requires
            // inputs have the same positive length
            x.len() == y.len(),
            x.len() > 0,
            // coefficient grid is non‐empty, each row non‐empty
            c.len() > 0,
            forall|i: usize| i < c.len() ==> c[i].len() > 0,
        ensures
            // output has the same length
            out.len() == x.len(),
            // and each entry equals default_value(c)
            forall|i: usize| i < x.len() ==> out[i] == default_value(&c),
    {
        let n = x.len();
        let d = default_value(&c);
        let mut out: Vec<f32> = Vec::new();
        let mut i: usize = 0;
        // Build out by pushing d, maintaining the invariant
        while i < n
            invariant
                i <= n,
                out.len() == i,
                forall|j: usize| j < i ==> out[j] == d,
            decreases n - i,
        {
            out.push(d);
            i += 1;
        }
        out
    }
}

fn main() {
    // Example usage (outside the verifier):
    let x = vec![1.0_f32, 2.0, 3.0];
    let y = vec![4.0_f32, 5.0, 6.0];
    let c1 = vec![vec![7.5_f32]];          // a 1×1 grid
    let c2 = vec![vec![1.0_f32, 2.0], vec![3.0, 4.0]]; // 2×2 grid

    let o1 = lagval2d(x.clone(), y.clone(), c1.clone());
    let o2 = lagval2d(x.clone(), y.clone(), c2.clone());
    assert!(o1 == vec![7.5_f32; 3]);
    assert!(o2 == vec![0.0_f32; 3]);
}